===== dev-login route =====
import { NextRequest, NextResponse } from "next/server";
import { cookies } from "next/headers";
import { db } from "@accessbuddy/db";
import { users } from "@accessbuddy/db";
import { eq } from "drizzle-orm";
import { isDevLoginEnabled } from "@/lib/auth";

/**
 * Dev-only login endpoint. Sets a cookie with the user email.
 *
 * Security F2 fix: this used to be gated on the client-controlled `Host`
 * header (`host.includes("localhost")`). A GCP HTTPS load balancer that
 * forwards a spoofed `Host: localhost` to the container turned that into a
 * one-request, no-secret-required global-admin takeover. Now gated on
 * `isDevLoginEnabled()` (NODE_ENV !== "production" AND ENABLE_DEV_LOGIN
 * === "true"), matching `getAuthUser`'s dev-login check exactly. Returns
 * 404 — not 403 — in production so the route's existence isn't disclosed.
 */
export async function POST(request: NextRequest) {
  if (!isDevLoginEnabled()) {
    return NextResponse.json({ error: "Not found" }, { status: 404 });
  }

  const { email } = await request.json();
  if (!email) {
    return NextResponse.json({ error: "Email required" }, { status: 400 });
  }

  // Verify user exists
  const [user] = await db
    .select()
    .from(users)
    .where(eq(users.email, email.toLowerCase().trim()))
    .limit(1);

  if (!user) {
    return NextResponse.json(
      { error: `No user found with email: ${email}` },
      { status: 404 }
    );
  }

  // Set a dev login cookie
  const cookieStore = await cookies();
  cookieStore.set("dev_login_email", email.toLowerCase().trim(), {
    httpOnly: true,
    secure: false,
    sameSite: "lax",
    path: "/",
    maxAge: 60 * 60 * 24 * 7, // 7 days
  });

  return NextResponse.json({ success: true, user: { email: user.email, firstName: user.firstName } });
}

