+// ── Session signing secret ──────────────────────────────────────────────────
+// session secret must fail closed on session verification specifically —
+// were HMAC-signed with `process.env.CRON_SECRET ?? "webauthn-session-secret"`
+// — a hardcoded fallback, and reuse of the cron auth secret. Given this
+// fall back to a literal, and never reuse CRON_SECRET: fail closed instead.
+const MIN_SESSION_SIGNING_SECRET_LENGTH = 32;
+let _sessionSigningSecret: string | null = null;
+ * Returns the dedicated session-signing secret, throwing if it is unset or
