+  if (_sessionSigningSecret) return _sessionSigningSecret;
=== auth-tokens table shape ===
 * consumed row is never accepted again. `attempts` caps brute-force guesses.
 */
export const otpCodes = pgTable(
  "otp_codes",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    email: text("email").notNull(),
    // Format: "<hex salt>:<hex scrypt hash>"
    codeHash: text("code_hash").notNull(),
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
    attempts: integer("attempts").notNull().default(0),
    consumedAt: timestamp("consumed_at", { withTimezone: true }),
    createdAt: timestamp("created_at", { withTimezone: true })
      .notNull()
      .defaultNow(),
  },
  (table) => ({
    emailIdx: index("otp_codes_email_idx").on(table.email),
  })
);

/**
 * Shared, cross-instance rate-limit buckets (fixed window). Replaces the
 * module-level in-memory Map so limits hold under Cloud Run scale-out /
 * cold start. `key` is the fully-qualified bucket identity, e.g.
 * `"send-otp:ip:1.2.3.4"` or `"send-otp:email:foo@bar.com"` — namespacing
 * is baked into the key by the caller (see lib/rate-limit.ts).
 */
export const rateLimitBuckets = pgTable("rate_limit_buckets", {
  key: text("key").primaryKey(),
  count: integer("count").notNull().default(1),
  resetAt: timestamp("reset_at", { withTimezone: true }).notNull(),
});
