import {
  pgTable,
  uuid,
  text,
  boolean,
  jsonb,
  timestamp,
  unique,
} from "drizzle-orm/pg-core";
import { tenants } from "./tenants";
import { users } from "./users";

/**
 * Per-tenant email configuration overrides.
 *
 * When a row exists for a tenant+eventId, its values override the code-defined
 * defaults from the email event registry. When no row exists, the system uses
 * defaults (all emails enabled, default subject/blocks).
 */
export const emailConfigurations = pgTable(
  "email_configurations",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    tenantId: uuid("tenant_id")
      .notNull()
      .references(() => tenants.id),
    eventId: text("event_id").notNull(),
    enabled: boolean("enabled").notNull().default(true),
    subjectOverride: text("subject_override"),
    blocks: jsonb("blocks"), // EmailBlock[] | null
    updatedAt: timestamp("updated_at", { withTimezone: true })
      .notNull()
      .defaultNow(),
    updatedBy: uuid("updated_by").references(() => users.id),
  },
  (table) => ({
    tenantEventUnique: unique("email_config_tenant_event_unique").on(
      table.tenantId,
      table.eventId
    ),
  })
);

